import { scrapeSearch } from './x-scrape.mjs';

export function isGithubReliabilityMention(tweet) {
  const text = String(tweet.text || '');
  return /github/i.test(text) && /\b(outages?|down|downtime|reliability|unreliable|unavailable|degraded)\b/i.test(text);
}

export async function scrapeWatchSearches(config, { scrape = scrapeSearch } = {}) {
  const queries = [
    { name: 'Entire', query: config.searchQuery },
    { name: 'GitHub reliability', query: config.githubSearchQuery },
  ];
  const results = await Promise.all(queries.map(async ({ name, query }) => {
    try {
      const result = await scrape({
        ...config,
        searchQuery: query,
        searchUrl: `https://x.com/search?q=${encodeURIComponent(query)}&src=typed_query&f=live`,
      });
      return { ...result, name, query };
    } catch (err) {
      throw new Error(`${name} search failed: ${err.message}`, { cause: err });
    }
  }));

  return {
    source: results.map((r) => `${r.name}:${r.source}`).join(', '),
    loginWall: results.some((r) => r.loginWall),
    tweets: results.flatMap((r) => r.tweets
      .filter((tweet) => r.name !== 'GitHub reliability' || isGithubReliabilityMention(tweet))
      .map((tweet) => ({
        ...tweet,
        searchTopic: r.name === 'GitHub reliability' ? 'github' : null,
      }))),
    searches: results,
  };
}
export const MATCH_HANDLE = 'handle';
export const MATCH_LINK = 'link';
export const MATCH_BOTH = 'both';
export const MATCH_GITHUB = 'github';

function classify(rawTweet) {
  // Reply beats quote: a quoted reply is still a reply to something of ours,
  // which is the more actionable framing.
  if (rawTweet.inReplyToStatusId) return 'reply';
  if (rawTweet.isQuoteStatus) return 'quote';
  return 'mention';
}

// The search asks for the handle OR the domain, so a result can arrive for
// either reason and the two read differently downstream: "replied to
// @entirehq" is wrong for a post that only shared a link.
//
// Neither signal present means the match came from something this record
// cannot see. The DOM path drops the "Replying to @entirehq" prefix from the
// tweet body, for one. Handle is the right answer there: it is what every
// result meant before the domain joined the query.
function matchedVia(rawTweet, own, domain) {
  const text = String(rawTweet.text || '').toLowerCase();
  const links = (Array.isArray(rawTweet.links) ? rawTweet.links : []).join(' ').toLowerCase();

  const byLink = Boolean(domain) && (links.includes(domain) || text.includes(domain));
  const byHandle = Boolean(own) && text.includes(`@${own}`);

  if (byLink && byHandle) return MATCH_BOTH;
  if (byLink) return MATCH_LINK;
  if (!byHandle && rawTweet.searchTopic === 'github') return MATCH_GITHUB;
  return MATCH_HANDLE;
}

export function filterAndClassify(rawTweets, { ownHandle, brandDomain } = {}) {
  if (!Array.isArray(rawTweets)) return [];
  const own = String(ownHandle || '').replace(/^@/, '').toLowerCase();
  const domain = String(brandDomain || '').toLowerCase();

  return rawTweets
    .filter((t) => {
      return (
        t &&
        typeof t === 'object' &&
        t.id &&
        t.author &&
        typeof t.text === 'string' &&
        typeof t.url === 'string' &&
        t.url &&
        !Number.isNaN(new Date(t.createdAt).getTime())
      );
    })
    .filter((t) => t.author.toLowerCase() !== own)
    .map((t) => ({
      id: t.id,
      author: t.author,
      text: t.text,
      url: t.url,
      createdAt: t.createdAt,
      kind: classify(t),
      matchedVia: matchedVia(t, own, domain),
      conversationId: t.conversationId ?? null,
      followers: t.followers ?? null,
      followsUs: t.followsUs ?? null,
      verified: t.verified ?? false,
    }))
    .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
}
import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

export const MAX_SEEN = 500;

// How long a thread's posting budget is remembered. A thread that drips one
// reply every poll would otherwise get a fresh budget every five minutes,
// which is the flood this is meant to stop, only slower.
export const CHAIN_WINDOW_MS = 6 * 60 * 60 * 1000;

// Bounds the file the same way MAX_SEEN does. Dropping the oldest entries
// first means the threads still being replied to are the ones kept.
export const MAX_CHAINS = 200;

const EMPTY = () => ({
  seen: [],
  chains: {},
  baselined: false,
  loginWallAlerted: false,
  backoffAlerted: false,
  emptyResultsAlerted: false,
});

function storePath(dataDir) {
  return join(dataDir, 'seen.json');
}

export function loadStore(dataDir) {
  const path = storePath(dataDir);
  if (!existsSync(path)) return EMPTY();
  try {
    const parsed = JSON.parse(readFileSync(path, 'utf8'));
    return Array.isArray(parsed?.seen)
      ? {
          seen: parsed.seen.map(String),
          chains: readChains(parsed?.chains),
          baselined: Boolean(parsed.baselined),
          loginWallAlerted: Boolean(parsed.loginWallAlerted),
          backoffAlerted: Boolean(parsed.backoffAlerted),
          emptyResultsAlerted: Boolean(parsed.emptyResultsAlerted),
        }
      : EMPTY();
  } catch {
    // A corrupt store is not worth crashing over — rebuilding the baseline
    // costs one silent poll.
    return EMPTY();
  }
}

// Atomic: write to a temp file in the same directory, then rename over the
// target. saveStore now runs once per announced tweet (and once per alert
// flag flip), so a crash mid-write is likelier than it used to be — a
// partial write would otherwise leave a corrupt file that loadStore's catch
// turns into a fresh, un-baselined store, silently re-baselining and
// swallowing every mention on the page from then on. A same-directory
// rename is atomic on the filesystems this runs on; a cross-device temp
// file would not be.
export function saveStore(dataDir, store) {
  mkdirSync(dataDir, { recursive: true });
  const path = storePath(dataDir);
  const tmpPath = join(dataDir, `.seen.json.${process.pid}.${Date.now()}.tmp`);
  writeFileSync(tmpPath, JSON.stringify(store, null, 2));
  renameSync(tmpPath, path);
}

// Pure. Returns a new store; never mutates the one passed in.
//
// `isBaseline` comes from the explicit `baselined` flag, never from an empty
// `seen` list: a poll can legitimately yield zero tweets after filtering, and
// re-baselining on the next poll would silently swallow the first real mention.
export function diffSeen(store, tweets) {
  const previous = Array.isArray(store?.seen) ? store.seen : [];
  const known = new Set(previous);
  const isBaseline = !store?.baselined;

  const fresh = [];
  const added = [];
  for (const tweet of tweets) {
    if (known.has(tweet.id)) continue;
    known.add(tweet.id);
    added.push(tweet.id);
    if (!isBaseline) fresh.push(tweet);
  }

  const seen = [...previous, ...added].slice(-MAX_SEEN);
  return {
    isBaseline,
    fresh,
    store: {
      seen,
      chains: readChains(store?.chains),
      baselined: true,
      loginWallAlerted: Boolean(store?.loginWallAlerted),
      backoffAlerted: Boolean(store?.backoffAlerted),
      emptyResultsAlerted: Boolean(store?.emptyResultsAlerted),
    },
  };
}

// Pure. Returns a new store; never mutates the one passed in. A no-op if
// `id` is already present, so re-marking a tweet doesn't grow the list
// twice. Callers persist one id at a time (see watch.mjs) so a process
// killed mid-batch can't have already recorded ids it never actually
// announced.
export function markSeen(store, id) {
  const previous = Array.isArray(store?.seen) ? store.seen : [];
  const seen = previous.includes(id) ? [...previous] : [...previous, id].slice(-MAX_SEEN);
  return {
    seen,
    chains: readChains(store?.chains),
    baselined: Boolean(store?.baselined),
    loginWallAlerted: Boolean(store?.loginWallAlerted),
    backoffAlerted: Boolean(store?.backoffAlerted),
    emptyResultsAlerted: Boolean(store?.emptyResultsAlerted),
  };
}

// A thread's posting budget: how many of its replies have been announced
// individually, and when the count started. Anything older than the window
// is gone, so a thread that goes quiet starts fresh if it wakes up again.
function readChains(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {};
  const chains = {};
  for (const [id, value] of Object.entries(raw)) {
    const count = Number(value?.count);
    const firstAt = Number(value?.firstAt);
    if (!Number.isFinite(count) || count <= 0 || !Number.isFinite(firstAt)) continue;
    chains[id] = { count: Math.floor(count), firstAt };
  }
  return chains;
}

function liveChains(chains, now) {
  const cutoff = now - CHAIN_WINDOW_MS;
  const live = Object.entries(chains).filter(([, c]) => c.firstAt > cutoff);
  live.sort((a, b) => a[1].firstAt - b[1].firstAt);
  return Object.fromEntries(live.slice(-MAX_CHAINS));
}

// Pure. How many individual posts each live thread has already spent.
export function chainCounts(store, now = Date.now()) {
  const chains = liveChains(readChains(store?.chains), now);
  return Object.fromEntries(Object.entries(chains).map(([id, c]) => [id, c.count]));
}

// Pure. Returns a new store with one more post charged to `chainId`. Called
// only after Slack accepts the post, so a failed delivery does not spend
// budget the channel never saw.
export function recordChainPost(store, chainId, now = Date.now()) {
  const chains = liveChains(readChains(store?.chains), now);
  const existing = chains[chainId];
  return {
    ...store,
    chains: liveChains(
      { ...chains, [chainId]: { count: (existing?.count ?? 0) + 1, firstAt: existing?.firstAt ?? now } },
      now,
    ),
  };
}

// Pure setters for the once-only alert flags. Each returns a NEW store with
// just that flag set; the rest of the store is carried through unchanged.
// Persisting these (rather than keeping them as module-level variables in
// watch.mjs) is what makes each alert fire exactly once per episode instead
// of once per process — the watcher is respawned on every SessionStart and
// every /clear, which would otherwise reset an in-memory flag and re-alert
// on a condition that never actually recovered.
export function setLoginWallAlerted(store, value) {
  return { ...store, loginWallAlerted: Boolean(value) };
}

export function setBackoffAlerted(store, value) {
  return { ...store, backoffAlerted: Boolean(value) };
}

export function setEmptyResultsAlerted(store, value) {
  return { ...store, emptyResultsAlerted: Boolean(value) };
}
// X ships more than one shape for the same data, so every accessor here is
// defensive: an entry we cannot read is skipped, never thrown on. Returning a
// short list is recoverable; crashing the poll loop is not.

function toIso(twitterDate) {
  // X sends "Tue Aug 18 14:02:11 +0000 2026", which Date parses correctly.
  const parsed = new Date(twitterDate);
  return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString();
}

function unwrapTweet(result) {
  if (!result || typeof result !== 'object') return null;
  // TweetWithVisibilityResults nests the real tweet one level down.
  const tweet = result.__typename === 'TweetWithVisibilityResults' ? result.tweet : result;
  if (!tweet || typeof tweet !== 'object') return null;
  return tweet;
}

function screenNameOf(tweet) {
  const user = tweet?.core?.user_results?.result;
  // Newer payloads put it under `core`, older ones under `legacy`.
  return user?.core?.screen_name || user?.legacy?.screen_name || null;
}

// X migrated the author counters out of `user.legacy` (now empty on live
// payloads) into `relationship_counts`. Both are read so an older payload
// shape, and the hand-built fixtures, keep working.
function authorSignal(tweet) {
  const user = tweet?.core?.user_results?.result ?? {};
  const followers = user?.relationship_counts?.followers ?? user?.legacy?.followers_count ?? null;
  const followedBy = user?.relationship_perspectives?.followed_by;
  return {
    followers: typeof followers === 'number' ? followers : null,
    // Whether this account follows @entirehq. Undefined means the payload did
    // not say, which must not be read as "does not follow us".
    followsUs: typeof followedBy === 'boolean' ? followedBy : null,
    verified: Boolean(user?.is_blue_verified || user?.verification?.verified),
  };
}

// X rewrites every link in `full_text` to a t.co shortlink, so the real
// destination survives only in the entities block. Reading it is what lets a
// post that links the site but never tags the account be recognized as one.
function linksOf(legacy) {
  const urls = legacy?.entities?.urls;
  if (!Array.isArray(urls)) return [];
  const links = [];
  for (const url of urls) {
    for (const value of [url?.expanded_url, url?.display_url]) {
      if (typeof value === 'string' && value) links.push(value);
    }
  }
  return links;
}

function entriesOf(payload) {
  const instructions =
    payload?.data?.search_by_raw_query?.search_timeline?.timeline?.instructions;
  if (!Array.isArray(instructions)) return [];
  return instructions
    .filter((i) => i?.type === 'TimelineAddEntries' && Array.isArray(i.entries))
    .flatMap((i) => i.entries);
}

// notify-slack.mjs interpolates `author` and `id` straight into a Slack
// link construct (`<url|text>`); a value containing `|` or `>` would break
// out of that syntax. X enforces this handle/id shape server-side, so this
// is defense in depth rather than a live exploit — but the guarantee
// downstream code relies on needs to be enforced where the data enters, not
// just assumed.
const HANDLE_RE = /^[A-Za-z0-9_]{1,15}$/;
const ID_RE = /^\d+$/;

export function parseTimelineJson(payload) {
  const tweets = [];
  const seenIds = new Set();
  for (const entry of entriesOf(payload)) {
    const tweet = unwrapTweet(entry?.content?.itemContent?.tweet_results?.result);
    if (!tweet) continue;

    const id = tweet.rest_id;
    const author = screenNameOf(tweet);
    const legacy = tweet.legacy;
    if (!id || !author || !legacy) continue;
    if (!HANDLE_RE.test(author) || !ID_RE.test(String(id))) continue;

    const createdAt = toIso(legacy.created_at);
    if (!createdAt) continue;

    // X can fire more than one SearchTimeline response per navigation (and a
    // single payload can carry more than one TimelineAddEntries instruction),
    // so the same tweet can arrive twice. Without this, a duplicate inflates
    // "tracking N" / "N tracked" counts even though nothing new happened.
    const idStr = String(id);
    if (seenIds.has(idStr)) continue;
    seenIds.add(idStr);

    tweets.push({
      id: idStr,
      author,
      text: legacy.full_text ?? '',
      url: `https://x.com/${author}/status/${id}`,
      createdAt,
      links: linksOf(legacy),
      // X's id for the whole thread: the root tweet's id, shared by every
      // reply under it. It is what tells twelve replies apart from twelve
      // unrelated mentions.
      conversationId: typeof legacy.conversation_id_str === 'string' ? legacy.conversation_id_str : null,
      inReplyToStatusId: legacy.in_reply_to_status_id_str ?? null,
      isQuoteStatus: Boolean(legacy.is_quote_status),
      isRetweet: Boolean(legacy.retweeted_status_result || legacy.retweeted_status_id_str),
      ...authorSignal(tweet),
    });
  }
  return tweets;
}

const STATUS_PATH_RE = /^(?:https?:\/\/(?:x|twitter)\.com)?\/([A-Za-z0-9_]{1,15})\/status\/(\d+)/;

// The DOM path can see that a "Replying to" block was rendered but not which
// status is being replied to. This sentinel says "a parent exists, identity
// unknown" — filter.mjs only ever checks presence, never the value.
export const UNKNOWN_PARENT = 'unknown';

export function parseDomRecords(records) {
  if (!Array.isArray(records)) return [];
  const tweets = [];
  const seen = new Set();

  for (const record of records) {
    if (!record || typeof record !== 'object') continue;

    const match = typeof record.permalink === 'string' && record.permalink.match(STATUS_PATH_RE);
    if (!match) continue;
    const [, pathAuthor, id] = match;

    if (seen.has(id)) continue;

    const createdAt = typeof record.datetime === 'string' ? toIso(record.datetime) : null;
    if (!createdAt) continue;

    // Prefer the permalink's author: the rendered handle can belong to a
    // quoted or retweeting account rather than the tweet's own author.
    const author = pathAuthor;

    seen.add(id);
    tweets.push({
      id,
      author,
      text: typeof record.text === 'string' ? record.text : '',
      url: `https://x.com/${author}/status/${id}`,
      createdAt,
      // The DOM shows a link as its display text ("entire.io/blog/…"), which
      // is the only form of the destination this path can see.
      links: Array.isArray(record.links) ? record.links.filter((l) => typeof l === 'string' && l) : [],
      // The rendered page never names the thread, so chain grouping falls
      // back to the author on this path.
      conversationId: null,
      inReplyToStatusId: record.hasReplyingTo ? UNKNOWN_PARENT : null,
      isQuoteStatus: Boolean(record.hasQuotedTweet),
      isRetweet: null,
    });
  }
  return tweets;
}
import { existsSync, readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

// One agent per machine. The label is fixed rather than per-project because
// launchd keys on it — two projects would silently fight over the same slot,
// so managesProject() below checks which project actually won.
export const LABEL = 'io.entire.entirehq-mention-watcher';

export function plistPath(home = homedir()) {
  return join(home, 'Library', 'LaunchAgents', `${LABEL}.plist`);
}

function xmlEscape(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

export function buildPlist({ nodePath, watchPath, projectDir, dataDir }) {
  const e = xmlEscape;
  return `<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key>
  <string>${e(LABEL)}</string>
  <key>ProgramArguments</key>
  <array>
    <string>${e(nodePath)}</string>
    <string>${e(watchPath)}</string>
  </array>
  <key>WorkingDirectory</key>
  <string>${e(projectDir)}</string>
  <key>EnvironmentVariables</key>
  <dict>
    <key>CLAUDE_PROJECT_DIR</key>
    <string>${e(projectDir)}</string>
    <key>PATH</key>
    <string>/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin</string>
  </dict>
  <key>RunAtLoad</key>
  <true/>
  <key>KeepAlive</key>
  <true/>
  <key>ThrottleInterval</key>
  <integer>60</integer>
  <key>StandardOutPath</key>
  <string>${e(join(dataDir, 'launchd.out.log'))}</string>
  <key>StandardErrorPath</key>
  <string>${e(join(dataDir, 'launchd.err.log'))}</string>
</dict>
</plist>
`;
}

// True only when an agent is installed AND it points at this project. A plist
// naming a different checkout means launchd is watching that one, not this
// one — the session hooks must still run their own watcher here.
export function managesProject(projectDir, home = homedir()) {
  const path = plistPath(home);
  if (!existsSync(path)) return false;
  try {
    return readFileSync(path, 'utf8').includes(`<string>${xmlEscape(projectDir)}</string>`);
  } catch {
    return false;
  }
}
