import { scrapeSearch } from './x-scrape.mjs';

const MAX_TWEET_AGE_MS = 3 * 24 * 60 * 60 * 1000;

export function isGithubReliabilityMention(tweet) {
  const text = String(tweet.text || '');
  return /github/i.test(text) && /\b(outages?|down|downtime|reliability|unreliable|unavailable|degraded)\b/i.test(text);
}

export async function scrapeWatchSearches(config, { scrape = scrapeSearch, now = Date.now() } = {}) {
  const queries = [
    { name: 'Entire', query: config.searchQuery },
    { name: 'GitHub reliability', query: config.githubSearchQuery },
  ];
  const results = await Promise.all(queries.map(async ({ name, query }) => {
    try {
      const result = await scrape({
        ...config,
        searchQuery: query,
        searchUrl: `https://x.com/search?q=${encodeURIComponent(query)}&src=typed_query&f=live`,
      });
      return { ...result, name, query };
    } catch (err) {
      throw new Error(`${name} search failed: ${err.message}`, { cause: err });
    }
  }));

  return {
    source: results.map((r) => `${r.name}:${r.source}`).join(', '),
    loginWall: results.some((r) => r.loginWall),
    tweets: results.flatMap((r) => r.tweets
      .filter((tweet) => {
        const createdAt = Date.parse(tweet.createdAt);
        return createdAt >= now - MAX_TWEET_AGE_MS && createdAt <= now;
      })
      .filter((tweet) => r.name !== 'GitHub reliability' || isGithubReliabilityMention(tweet))
      .map((tweet) => ({
        ...tweet,
        searchTopic: r.name === 'GitHub reliability' ? 'github' : null,
      }))),
    searches: results,
  };
}
export const REPLY_TEXT = '@goentire is up. entire.com';
export const MAX_REPLY_AGE_MS = 60 * 60 * 1000;

export function isGithubOutage(tweet) {
  const text = String(tweet.text || '').replace(/https?:\/\/\S+/gi, '');
  if (tweet.isRetweet !== false || /^RT\s+@/i.test(text)) return false;
  if (!/\bgithub\b/i.test(text)) return false;
  if (/\b(?:not|never|no longer)\s+(?:currently\s+)?(?:down|unavailable|having an outage)\b|\bno\s+(?:github\s+)?outage|\b(?:when|imagine|what if)\s+github\b|\b(?:back up|resolved|recovered)\b/i.test(text)) return false;
  if (/\bif\s+github\b/i.test(text) && !/\b(?:asking|wondering|know|checking|check|see|sure)\s+if\s+github\b/i.test(text)) return false;

  const service = 'github(?:\\s+(?:actions|api|pages|packages|copilot))?';
  return new RegExp(`\\b${service}(?:['’]s)?\\s+(?:(?:is|was|has|seems|looks|went|gone|going|currently|still|apparently|to|be)\\s+){0,4}(?:down|unavailable|degraded)\\b(?!\\s+(?:to|the)\\b)`, 'i').test(text)
    || new RegExp(`\\b${service}(?:['’]s)?\\s+(?:(?:is|was|has|having|experiencing|suffering|from|a|an|another|major|new|current|ongoing|global|partial|service)\\s+){0,6}(?:outages?|downtime)\\b`, 'i').test(text)
    || /\b(?:outages?|downtime)\s+(?:(?:on|at|of|with|for|affecting)\s+)?github\b/i.test(text);
}

export function replyCandidates(tweets, config, { since = 0, now = Date.now() } = {}) {
  const excluded = new Set([config.replyHandle, config.ownHandle, ...(config.mutedHandles || [])]
    .map((handle) => String(handle || '').replace(/^@/, '').toLowerCase()));
  const unique = new Map();
  for (const tweet of tweets) {
    const created = Date.parse(tweet.createdAt);
    if (!/^\d+$/.test(tweet.id) || !/^[a-z0-9_]{1,15}$/i.test(tweet.author)) continue;
    if (!Number.isFinite(created) || created <= since || created > now || now - created > MAX_REPLY_AGE_MS) continue;
    if (excluded.has(tweet.author.toLowerCase()) || !isGithubOutage(tweet)) continue;
    unique.set(tweet.id, tweet);
  }
  return [...unique.values()].sort((a, b) => Date.parse(a.createdAt) - Date.parse(b.createdAt));
}
import Anthropic from '@anthropic-ai/sdk';

export const MODEL = 'claude-haiku-5-5';

const SYSTEM = `You triage public X/Twitter mentions of @entirehq, a git hosting platform built for AI coding agents, founded by GitHub's former CEO. Its site is entire.io.

A mention reaches you either because it tags the account or because it links the site. A post that links entire.io without tagging @entirehq is a real mention. Judge it on the same terms, and remember the author is not expecting a reply.

Judge whether the @entirehq team should act on a mention right now. Act means: reply, repost, or route it to someone internally.

You also monitor GitHub outage and reliability discussions from a separate search. These authors have not necessarily mentioned Entire. Treat concrete reports of GitHub service failures, degraded performance, or recurring reliability problems as PRIORITY; generic commentary is ROUTINE. Do not assume every result confirms an active outage.

PRIORITY: a question or support request aimed at the product; a user reporting a real problem; a notable endorsement worth reposting; someone comparing @entirehq to a competitor or saying they are switching; a request for access or a demo.
ROUTINE: generic praise, emoji-only replies, tangential mentions in an unrelated thread, pile-on replies that add nothing, chatter between other people where @entirehq is incidental.
IGNORE: spam, crypto/airdrop bait, unrelated accounts that merely contain the string, engagement farming.

Judge the text on its own merits. Follower counts are scored separately and must not influence this call.`;

const TOOL = {
  name: 'record_triage',
  description: 'Record the triage decision for one mention.',
  strict: true,
  input_schema: {
    type: 'object',
    properties: {
      tier: { type: 'string', enum: ['PRIORITY', 'ROUTINE', 'IGNORE'] },
      reason: { type: 'string', description: 'At most eight words, lowercase, no trailing period.' },
    },
    required: ['tier', 'reason'],
    additionalProperties: false,
  },
};

const MATCHED = {
  github: 'GitHub outage/reliability search, does not tag the account or link the site',
  handle: 'tags the account',
  link: 'links the site, does not tag the account',
  both: 'tags the account and links the site',
};

export function buildPrompt(tweet) {
  return [
    `Author: @${tweet.author}`,
    `Kind: ${tweet.kind}`,
    `Matched: ${MATCHED[tweet.matchedVia] ?? MATCHED.handle}`,
    `Text: ${tweet.text}`,
  ].join('\n');
}

// Resolves rather than rejects. The caller is a poll loop whose deterministic
// score is a complete answer on its own, so a classifier outage degrades the
// tiering instead of dropping the notification.
export async function classify(tweet, { client, timeoutMs = 15000 } = {}) {
  if (!client) return { ok: false, tier: null, reason: null, error: 'no client' };

  try {
    const response = await client.messages.create(
      {
        model: MODEL,
        max_tokens: 256,
        system: SYSTEM,
        output_config: { effort: 'low' },
        tools: [TOOL],
        tool_choice: { type: 'tool', name: TOOL.name },
        messages: [{ role: 'user', content: buildPrompt(tweet) }],
      },
      { timeout: timeoutMs },
    );

    if (response.stop_reason === 'refusal') {
      return { ok: false, tier: null, reason: null, error: 'refusal' };
    }

    const call = response.content.find((block) => block.type === 'tool_use');
    if (!call) return { ok: false, tier: null, reason: null, error: 'no tool_use block' };

    const { tier, reason } = call.input ?? {};
    if (!['PRIORITY', 'ROUTINE', 'IGNORE'].includes(tier)) {
      return { ok: false, tier: null, reason: null, error: `bad tier: ${tier}` };
    }
    return { ok: true, tier, reason: String(reason ?? '').slice(0, 80) };
  } catch (err) {
    return { ok: false, tier: null, reason: null, error: err?.message ?? String(err) };
  }
}

export function createClient(apiKey) {
  return apiKey ? new Anthropic({ apiKey }) : null;
}
import { PRIORITY_THRESHOLD, scoreTweet, isTeam } from './score.mjs';

export const PRIORITY = 'priority';
export const ROUTINE = 'routine';
export const MUTED = 'muted';

// The two signals answer different questions and neither subsumes the other:
// the score measures reach (how many people see this), the classifier measures
// intent (is this worth answering). Either one alone mis-ranks a common case —
// a thoughtful support question from a 200-follower account, or an emoji reply
// from someone with 40k.
export function decideTier({ tweet, score, reasons, verdict, mutedHandles = [], teamHandles = [] }) {
  if (isTeam(tweet.author, mutedHandles)) {
    return { tier: MUTED, reasons: ['muted account'], verdict: null };
  }

  const onTeam = isTeam(tweet.author, teamHandles);
  const llm = verdict?.ok ? verdict.tier : null;
  const combined = [...reasons];
  if (verdict?.ok && verdict.reason) combined.push(verdict.reason);

  // A team member's own reply is a receipt, never a call to action.
  if (onTeam) return { tier: ROUTINE, reasons: combined, verdict: llm };

  // A verdict wins whenever the classifier actually read the text. The score
  // measures reach, and reach does not make an emoji reply worth answering —
  // letting a high score override an explicit ROUTINE put eleven emoji
  // tag-chain replies from one 2.2k-follower account into priority on the
  // first live run. IGNORE is demoted rather than dropped: a false negative on
  // a real support question would be invisible, and silence is the one failure
  // this tool exists to prevent.
  if (llm === 'ROUTINE' || llm === 'IGNORE') return { tier: ROUTINE, reasons: combined, verdict: llm };

  if (llm === 'PRIORITY') return { tier: PRIORITY, reasons: combined, verdict: llm };

  // No usable verdict (classifier off, errored, or timed out): the score
  // decides alone. This is the degraded path and it is meant to still work.
  if (score >= PRIORITY_THRESHOLD) return { tier: PRIORITY, reasons: combined, verdict: llm };

  return { tier: ROUTINE, reasons: combined, verdict: llm };
}

export function triage(tweet, { mutedHandles = [], teamHandles = [], verdict = null } = {}) {
  const { score, reasons } = scoreTweet(tweet, { teamHandles });
  return { ...decideTier({ tweet, score, reasons, verdict, mutedHandles, teamHandles }), score };
}
import { MATCH_LINK, MATCH_BOTH, MATCH_GITHUB } from './filter.mjs';

const VERB = {
  mention: 'mentioned',
  reply: 'replied to',
  quote: 'quoted',
};

// Only used by callers that have no config in hand (the tests). The watcher
// passes the live values, so a renamed account or domain cannot drift.
const BRAND = { handle: 'entirehq', domain: 'entire.io' };

const MAX_BODY = 500;

export function withGithubStatus(payload, status) {
  const description = status?.ok
    ? `${status.description} — ${status.active ? 'current disruption confirmed' : 'no current disruption confirmed'}`
    : 'Check unavailable — current status unknown';
  const details = status?.ok
    ? [...status.components.map((c) => c.name), ...status.incidents.map((i) => i.name)]
    : [];
  const checked = Date.parse(status?.checkedAt);
  const timestamp = Number.isFinite(checked)
    ? ` · checked <!date^${Math.floor(checked / 1000)}^{date_short_pretty} at {time}|${status.checkedAt}>`
    : '';
  const summary = body([description, ...details].join(' · '));
  return {
    ...payload,
    text: `${payload.text} · githubstatus.com: ${summary}`,
    blocks: [...payload.blocks, {
      type: 'context',
      elements: [{
        type: 'mrkdwn',
        text: `<https://www.githubstatus.com/|githubstatus.com>: ${escapeSlack(summary)}${timestamp}`,
      }],
    }],
  };
}

// Slack mrkdwn treats these three as control characters. Tweet text is
// untrusted input — without this a tweet could forge a link in our channel.
export function escapeSlack(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function body(text) {
  const flat = String(text).replace(/\s+/g, ' ').trim();
  return flat.length > MAX_BODY ? `${flat.slice(0, MAX_BODY - 1)}…` : flat;
}

function reach(tweet) {
  const n = Number(tweet.followers);
  if (!Number.isFinite(n) || n <= 0) return null;
  if (n >= 10000) return `${Math.round(n / 1000)}k followers`;
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k followers`;
  return `${n} followers`;
}

function meta(tweet, triage) {
  const r = reach(tweet);
  const reasons = (triage?.reasons ?? []).filter((x) => x !== r);
  return reasons.slice(0, 3).join(', ') || tweet.kind;
}

// Priority gets the full card and a leading marker; routine collapses to one
// line. The whole point of the split is that a skimming reader can tell them
// apart without reading either, so the shapes must differ, not just the words.
// The kind leads every line, in the same slot on both tiers, so scanning the
// left edge answers "reply or tweet?" without reading the line. It used to sit
// mid-chain in the trailing metadata, where it was effectively invisible.
const KIND_LABEL = {
  mention: 'TWEET',
  reply: 'REPLY',
  quote: 'QUOTE',
};

export function kindLabel(kind) {
  return KIND_LABEL[kind] ?? 'TWEET';
}

// What the post did to us. A link-only share never tagged the account, so the
// reply/quote verb would misreport it: the kind label already carries whether
// it was a reply, and the verb slot has to say what it matched on instead.
function action(tweet, brand) {
  if (tweet.matchedVia === MATCH_GITHUB) return 'discussed GitHub reliability';
  if (tweet.matchedVia === MATCH_LINK) return `linked ${brand.domain}`;
  return `${VERB[tweet.kind] ?? 'mentioned'} @${brand.handle}`;
}

function linkTag(tweet, brand) {
  if (tweet.matchedVia === MATCH_GITHUB) return 'GitHub reliability';
  return tweet.matchedVia === MATCH_LINK || tweet.matchedVia === MATCH_BOTH
    ? `links ${brand.domain}`
    : null;
}

export function buildTweetMessage(tweet, triage = null, brand = BRAND) {
  const did = action(tweet, brand);
  const epoch = Math.floor(new Date(tweet.createdAt).getTime() / 1000);
  const handle = escapeSlack(tweet.author);
  const profile = `https://x.com/${encodeURIComponent(tweet.author)}`;
  const label = kindLabel(tweet.kind);
  const r = reach(tweet);
  const tag = linkTag(tweet, brand);

  if (triage && triage.tier === 'routine') {
    return {
      text: `${label} \u00b7 @${handle} ${did}`,
      blocks: [
        {
          type: 'context',
          elements: [
            {
              type: 'mrkdwn',
              text:
                `\`${label}\` <${profile}|@${handle}> \u00b7 ` +
                `${escapeSlack(body(tweet.text).slice(0, 140))} \u00b7 ` +
                [`<${tweet.url}|open>`, r, tag].filter(Boolean).join(' \u00b7 '),
            },
          ],
        },
      ],
    };
  }

  return {
    text: `\u2605 ${label} \u00b7 @${handle} ${did}`,
    blocks: [
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text:
            `*\u2605 \`${label}\`* <${profile}|@${handle}>` +
            (r ? ` \u00b7 ${r}` : '') +
            `\n>${escapeSlack(body(tweet.text))}`,
        },
      },
      {
        type: 'context',
        elements: [
          {
            type: 'mrkdwn',
            text: [
              `<${tweet.url}|View on X>`,
              escapeSlack(meta(tweet, triage)),
              tag,
              `<!date^${epoch}^{date_short_pretty} at {time}|${tweet.createdAt}>`,
            ]
              .filter(Boolean)
              .join(' \u00b7 '),
          },
        ],
      },
    ],
  };
}

// The one line a thread gets once it is out of budget. It names who is in it
// and where to open it; the posts themselves are routine by definition, so
// the count is the information.
export function buildChainMessage({ count, authors = [], moreAuthors = 0, url }) {
  const noun = count === 1 ? 'reply' : 'replies';
  const who = [
    ...authors.map((author) => `@${escapeSlack(author)}`),
    moreAuthors > 0 ? `+${moreAuthors}` : null,
  ]
    .filter(Boolean)
    .join(', ');

  return {
    text: `CHAIN \u00b7 ${count} more ${noun} in this thread`,
    blocks: [
      {
        type: 'context',
        elements: [
          {
            type: 'mrkdwn',
            text: [`\`CHAIN\` ${count} more ${noun} in this thread`, who, `<${url}|open>`]
              .filter(Boolean)
              .join(' \u00b7 '),
          },
        ],
      },
    ],
  };
}

export function buildAlertMessage(text) {
  return {
    text,
    blocks: [{ type: 'section', text: { type: 'mrkdwn', text: escapeSlack(text) } }],
  };
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Resolves rather than rejects: the caller is a poll loop that must survive a
// bad Slack day, and the terminal has already shown the user this tweet.
export async function postToSlack(webhookUrl, payload, options = {}) {
  const { fetchImpl = fetch, retryDelayMs = 1000 } = options;
  let status = 0;

  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      const response = await fetchImpl(webhookUrl, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(payload),
      });
      status = response.status;
      if (response.ok) return { ok: true, status, attempts: attempt };
    } catch {
      status = 0;
    }
    if (attempt === 1) await sleep(retryDelayMs);
  }

  return { ok: false, status, attempts: 2 };
}

