const now = Date.parse('2026-10-27T12:00:00Z');
const raw = (id, text) => ({
  id, text, author: 'dev', url: `https://x.com/dev/status/${id}`,
  createdAt: '2026-10-27T06:00:00Z', conversationId: 'thread',
